"""Validation rules migrated from legacy/account_rules.vrl."""

from decimal import Decimal
from typing import Any


def _value(record: dict, column: str) -> Any:
    value = record.get(column, "")
    return "" if value is None else value


def _text(record: dict, column: str) -> str:
    value = _value(record, column)
    return value if isinstance(value, str) else str(value)


def _number(value: Any) -> Decimal:
    if value is None or value == "":
        return Decimal(0)
    return Decimal(str(value))


def validate(
    record: dict,
    old: dict | None = None,
    event: str = "INSERT",
    today: str = "20260901",
) -> list[dict]:
    """Evaluate applicable account rules in legacy rule-file order."""
    del today  # Part of the fixed interface; unused by these rules.

    errors: list[dict] = []

    if event in ("INSERT", "UPDATE"):
        # ACC-001
        if len(_text(record, "ACCT_NM")) < 2:
            errors.append(
                {
                    "code": "E1001",
                    "message": "Account name too short",
                    "severity": "BLOCK",
                }
            )

        # ACC-002
        if _text(record, "ACCT_TYP") not in ("C", "P", "R", "X"):
            errors.append(
                {
                    "code": "E1002",
                    "message": "Invalid account type",
                    "severity": "BLOCK",
                }
            )

        # ACC-003
        ann_rev = _value(record, "ANN_REV")
        if _number(0 if ann_rev == "" else ann_rev) < 0:
            errors.append(
                {
                    "code": "E1003",
                    "message": "Annual revenue negative",
                    "severity": "BLOCK",
                }
            )

    if event == "UPDATE":
        # ACC-004
        old_record = old if old is not None else {}
        releasing_hold = (
            _text(old_record, "CRED_HOLD") == "Y"
            and _text(record, "CRED_HOLD") == "N"
            and _number(_value(record, "CRED_LIMIT")) <= 0
        )
        if releasing_hold:
            errors.append(
                {
                    "code": "E1004",
                    "message": "Cannot release credit hold with zero credit limit",
                    "severity": "BLOCK",
                }
            )

    if event in ("INSERT", "UPDATE"):
        # ACC-005
        if len(_text(record, "REGION_CD")) != 3:
            errors.append(
                {
                    "code": "E1005",
                    "message": "Region code must be 3 chars",
                    "severity": "WARN",
                }
            )

    return errors


def is_blocked(errors: list[dict]) -> bool:
    """Return True when at least one validation failure blocks the write."""
    return any(error.get("severity") == "BLOCK" for error in errors)
